WITH valid AS (SELECT id, promo_code, ends_on, discount_pct, LOWER(channel) AS channel_lower FROM promotions WHERE channel IS NOT NULL AND YEAR(starts_on) >= 2023), scored AS (SELECT *, LAG(discount_pct) OVER (PARTITION BY promo_code ORDER BY discount_pct, id) AS prev_discount_pct, LEAD(discount_pct) OVER (PARTITION BY promo_code ORDER BY discount_pct, id) AS next_discount_pct, ROW_NUMBER() OVER (PARTITION BY promo_code ORDER BY discount_pct, id) AS row_seq, SUM(discount_pct) OVER (PARTITION BY DATE_TRUNC('WEEK', ends_on), promo_code) AS ends_on_period_sum_discount_pct FROM valid), base AS (SELECT id, promo_code, ends_on, channel_lower, prev_discount_pct, next_discount_pct, ends_on_period_sum_discount_pct, TRIM(promo_code) AS clean_promo_code FROM scored WHERE ends_on >= TO_DATE('2023-08-26')), cleaned AS (SELECT *, ROUND(ends_on_period_sum_discount_pct, 0) AS ends_on_period_sum_discount_pct_rounded FROM base WHERE MONTH(ends_on) IN (1, 6, 8)) SELECT id, promo_code, ends_on, prev_discount_pct, ends_on_period_sum_discount_pct, clean_promo_code, CASE WHEN promo_code RLIKE '^(WELCOME5|BUNDLE)$' THEN 'GROUP_A' WHEN promo_code RLIKE '^(SPRING10|VIP)$' THEN 'OTHER_ZONE' ELSE 'CORE' END AS promo_code_zone FROM cleaned;
